if (N % 2 != 0) {
    throw std::invalid_argument("Number of intervals must be even");
}

double h = (b - a) / N;
double sum = f(a) + f(b);

for (int i = 1; i < N; i++) {
    double x = a + i * h;
    if (i % 2 == 0) {
        sum += 2 * f(x);
    } else {
        sum += 4 * f(x);
    }
}

return sum * h / 3;

